sql.where:
SD.OrderState IN ('배송시작', '배송완료')
AND SD.InvNo IS NOT NULL AND SD.InvNo <> ''
AND SD.SlnkOrderCode IS NOT NULL AND SD.SlnkOrderCode <> ''
AND SD.ShipCmpletDate >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

    AND SD.ChnlCode NOT IN #{c}

AND SD.ShopCode = #{shopCode}
AND SD.ChnlCode = #{chnlCode}
AND Ch.SvcCode = #{svcCode}
AND NOT EXISTS (
    SELECT 1 FROM shopwizard.tPrdSlinkLog L
    WHERE L.LogType = '송장' AND L.OrderNo = SD.OrderNo AND L.OrderProdNo = SD.OrderProdNo AND L.OrderChangeNo = SD.OrderChangeNo
      AND L.InvNo = SD.InvNo AND L.ResultType NOT IN ('dry', 'false', 'error')
)

mapper.select:
SELECT 


ORDER BY SD.ShipCmpletDate DESC, SD.OrderNo DESC, SD.OrderProdNo, SD.OrderChangeNo
LIMIT #{limit}
